				case WazaNo.TOKINOHOUKOU:
					return monsNo == MonsNo.DHIARUGA && formNo == 0;
				case WazaNo.AKUUSETUDAN:
					return monsNo == MonsNo.PARUKIA && formNo == 0;
				case WazaNo.GARYOUTENSEI:
