			if (npcDatas.Length < choiceNum)
			{
				EmitLog(string.Format("Record Length under create count : {0}", choiceNum));
				return choiceDatas;
			}

			int[] shuffledIndexes = CreateShuffledIndexArray(npcDatas.Length);
			for (int i = 0; i < choiceNum; i++)
				choiceDatas[i] = npcDatas[shuffledIndexes[i]];

