		private static int[] CreateShuffledIndexArray(int arrayLength) {
			int[] indexes = new int[arrayLength];
			for (int i = 0; i < indexes.Length; i++)
				indexes[i] = i;

			for (int i = 0; i < arrayLength; i++)
			{
				int j = UnityEngine.Random.Range(i, arrayLength);
				int tmp = indexes[i];
				indexes[i] = indexes[j];
				indexes[j] = tmp;
			}
			return indexes;
		}
		public static global::Pml.WazaNo LotNPCUseWazaNo(global::XLSXContent.ContestMasterDatas.SheetNPCData npcData) {
			int[] probabilityArray = npcData.probabilityArray;
			int total = 0;
			for (int i = 0; i < probabilityArray.Length; i++)
				total += probabilityArray[i];

			int lot = UnityEngine.Random.Range(0, total);
			int sum = 0;
			for (int i = 0; i < probabilityArray.Length; i++)
			{
				if (probabilityArray[i] <= 0)
					continue;

				sum += probabilityArray[i];
				if (lot <= sum)
				{
					switch (i)
					{
						case 0: return (WazaNo)npcData.waza1;
						case 1: return (WazaNo)npcData.waza2;
						case 2: return (WazaNo)npcData.waza3;
						case 3: return (WazaNo)npcData.waza4;
					}
				}
			}

			EmitLog("Failed Choose Npc Waza No");
			return (WazaNo)npcData.waza1;
		}
